export type ScenarioField = {
  label: string;
  options: string[];
  answer: string;
};

type QuestionBase = {
  id: string;
  /** Lectures this question draws on. Mixed quizzes only use it once all are done. */
  lectures: number[];
  tags: string[];
  prompt: string;
  explanation: string;
  /** Heading id in the lesson page (generated by rehype-slug). */
  lessonAnchor: string;
};

export type ScenarioQuestion = QuestionBase & {
  type: "scenario";
  fields: ScenarioField[];
};

export type McqQuestion = QuestionBase & {
  type: "mcq";
  options: string[];
  answer: string;
};

export type OrderQuestion = QuestionBase & {
  type: "order";
  /** Steps in the correct order; shown shuffled. */
  steps: string[];
};

export type Question = ScenarioQuestion | McqQuestion | OrderQuestion;

/** What the learner submitted, per question type. */
export type Response =
  | { type: "scenario"; values: string[] }
  | { type: "mcq"; value: string }
  | { type: "order"; sequence: string[] };

export type Lecture = {
  id: number;
  slug: string;
  title: string;
  summary: string;
  /** Source video; null when the lesson was written from the topic alone (e.g. members-only video). */
  videoUrl: string | null;
  /** True when the lesson was written from the topic even though a video exists (it's linked as related). */
  writtenFromTopic?: boolean;
  minutes: number;
  available: boolean;
};

export type Course = {
  /** URL segment and progress-key prefix, e.g. "backend". */
  id: string;
  title: string;
  summary: string;
  /** Creator of the source playlist. */
  author: string;
  playlistUrl: string;
  /** What the source is; defaults to "playlist". */
  sourceKind?: "playlist" | "course";
  /** Built from non-public material, so its pages need the passcode. */
  private?: boolean;
};
